int transform_strings(const char** in, size_t n, char*** out, size_t* out_n, const char* op){
  if(!in||!out||!out_n) return -1;
  *out_n = n;
  *out = (char**)malloc(n*sizeof(char*));
  for(size_t i=0;i<n;i++){
    const char* s = in[i];
    size_t len = strlen(s);
    char* t = (char*)malloc(len+1);
    for(size_t j=0;j<len;j++) t[j] = (char)toupper((unsigned char)s[j]);
    t[len]='\0';
    (*out)[i]=t;
  }
  return 0;
}
